/** Extra X offset so wordmark clears the icon badge (path extends left of M330). */
const LOGO_WORDMARK_OFFSET = 56;

const LOGO_VIEWBOX_WIDTH = 854 + LOGO_WORDMARK_OFFSET;

type LogoProps = {
  className?: string;
};

export function FacilaLogo({ className }: LogoProps) {
  return (
    <FacilaLogoGraphic
      className={className}
      badgeClassName="fill-navy"
      symbolClassName="fill-primary-foreground"
      wordmarkClassName="fill-navy"
    />
  );
}

export function FacilaLogoWhite({ className }: LogoProps) {
  return (
    <FacilaLogoGraphic
      className={className}
      badgeClassName="fill-primary-foreground"
      symbolClassName="fill-navy"
      wordmarkClassName="fill-primary-foreground"
    />
  );
}

function SymbolBadgeGraphic({
  badgeClassName,
  symbolClassName,
}: {
  badgeClassName: string;
  symbolClassName: string;
}) {
  return (
    <>
      <rect width="278" height="278" rx="52" className={badgeClassName} />
      <svg
        x="43.44"
        y="26.06"
        width="191.13"
        height="225.88"
        viewBox="0 0 226 278"
        className={symbolClassName}
      >
        <path d={SYMBOL_PATH} />
      </svg>
    </>
  );
}

function FacilaLogoGraphic({
  className,
  badgeClassName,
  symbolClassName,
  wordmarkClassName,
}: LogoProps & {
  badgeClassName: string;
  symbolClassName: string;
  wordmarkClassName: string;
}) {
  return (
    <svg
      viewBox={`0 0 ${LOGO_VIEWBOX_WIDTH} 278`}
      role="img"
      aria-label="Facila"
      className={cn("h-8 w-auto", className)}
    >
      <SymbolBadgeGraphic
        badgeClassName={badgeClassName}
        symbolClassName={symbolClassName}
      />
      <g transform={`translate(${LOGO_WORDMARK_OFFSET}, 0)`}>
        <path d={WORDMARK_PATH} className={wordmarkClassName} />
      </g>
    </svg>
  );
}

function FacilaSymbolBadge({
  className,
  badgeClassName,
  symbolClassName,
}: LogoProps & {
  badgeClassName: string;
  symbolClassName: string;
}) {
  return (
    <svg
      viewBox="0 0 278 278"
      role="img"
      aria-hidden="true"
      className={cn("h-8 w-auto", className)}
    >
      <SymbolBadgeGraphic
        badgeClassName={badgeClassName}
        symbolClassName={symbolClassName}
      />
    </svg>
  );
}

export function FacilaSymbol({ className }: LogoProps) {
  return (
    <FacilaSymbolBadge
      className={className}
      badgeClassName="fill-navy"
      symbolClassName="fill-primary-foreground"
    />
  );
}

export function FacilaSymbolWhite({ className }: LogoProps) {
  return (
    <FacilaSymbolBadge
      className={className}
      badgeClassName="fill-primary-foreground"
      symbolClassName="fill-navy"
    />
  );
}
